'use client';

import { useState } from 'react';

import { ArrowRightIcon, CodeIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { CommandRow } from './command-row';
import {
  CARD,
  DEFAULT_MANAGER,
  INSTALL_COMMANDS,
  type InstallCommand,
  type PackageManagerId,
} from './data';

function isPackageManagerId(value: unknown): value is PackageManagerId {
  return INSTALL_COMMANDS.some((entry) => entry.id === value);
}

function commandOf(id: PackageManagerId) {
  const found = INSTALL_COMMANDS.find((entry) => entry.id === id);
  const fallback: InstallCommand = INSTALL_COMMANDS[0];
  const entry = found ?? fallback;
  return entry.command;
}

export default function Ctas02() {
  const [manager, setManager] = useState<PackageManagerId>(DEFAULT_MANAGER);
  const command = commandOf(manager);

  function changeManager(value: unknown) {
    if (isPackageManagerId(value)) {
      setManager(value);
    }
  }

  return (
    <section className='px-4 py-12 sm:px-6 sm:py-16 lg:px-8'>
      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] mx-auto grid max-w-4xl gap-8 rounded-xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] sm:p-8 md:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)] md:items-center md:gap-10'>
        <div className='flex flex-col items-start gap-4'>
          <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
            <CodeIcon />
          </span>
          <div className='flex flex-col gap-2'>
            <p className='text-primary-ink text-xs font-medium'>
              {CARD.eyebrow}
            </p>
            <h2 className='text-xl font-semibold text-balance'>{CARD.title}</h2>
            <p className='text-muted-foreground text-sm text-pretty'>
              {CARD.description}
            </p>
          </div>
        </div>
        <div className='flex min-w-0 flex-col gap-3'>
          <Tabs value={manager} onValueChange={changeManager}>
            <TabsList variant='segmented' aria-label='Package manager'>
              {INSTALL_COMMANDS.map((entry) => (
                <TabsTab key={entry.id} value={entry.id}>
                  {entry.label}
                </TabsTab>
              ))}
            </TabsList>
          </Tabs>
          <CommandRow command={command} />
          <div className='flex flex-wrap gap-x-5 gap-y-1'>
            {CARD.links.map((link) => (
              <Button
                key={link.label}
                variant='link'
                className='h-auto px-0'
                nativeButton={false}
                render={<a href={link.href} />}
              >
                {link.label}
                <ArrowRightIcon className='size-3.5' />
              </Button>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

type CopyState = 'idle' | 'copied' | 'failed';

const COPIED_RESET_MS = 1500;

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const TEXT_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function textVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return TEXT_VARIANTS;
}

function copyGlyphOf(isCopied: boolean) {
  if (isCopied) {
    return {
      key: 'copied',
      icon: <CheckIcon className='text-success-foreground' />,
    };
  }
  return { key: 'copy', icon: <CopyIcon /> };
}

function copyLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Copied';
  }
  return 'Copy the command';
}

export function CommandRow({ command }: { command: string }) {
  const [copyState, setCopyState] = useState<CopyState>('idle');
  const shouldReduceMotion = useReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const textVariants = textVariantsOf(shouldReduceMotion);
  const isCopied = copyState === 'copied';
  const hasFailed = copyState === 'failed';
  const glyph = copyGlyphOf(isCopied);
  const copyLabel = copyLabelOf(isCopied);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setCopyState('idle');
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copyCommand() {
    try {
      await navigator.clipboard.writeText(command);
      setCopyState('copied');
    } catch {
      setCopyState('failed');
    }
  }

  return (
    <div className='flex flex-col gap-2'>
      <div className='bg-foreground/[0.04] hairline-ring ring-border flex h-11 items-center gap-2 rounded-lg ps-3.5 pe-1.5'>
        <code className='relative flex min-w-0 flex-1 overflow-hidden font-mono text-[13px]'>
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.span
              key={command}
              className='truncate'
              variants={textVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
            >
              {command}
            </motion.span>
          </AnimatePresence>
        </code>
        <Tooltip>
          <TooltipTrigger
            delay={0}
            render={
              <Button
                variant='ghost'
                size='icon'
                onClick={copyCommand}
                aria-label={copyLabel}
              />
            }
          >
            <AnimatePresence mode='popLayout' initial={false}>
              <motion.span
                key={glyph.key}
                className='flex'
                variants={iconVariants}
                initial='enter'
                animate='visible'
                exit='exit'
                transition={SWAP_TRANSITION}
              >
                {glyph.icon}
              </motion.span>
            </AnimatePresence>
          </TooltipTrigger>
          <TooltipContent>{copyLabel}</TooltipContent>
        </Tooltip>
      </div>
      <p aria-live='polite' className='text-destructive-ink min-h-4 text-xs'>
        {hasFailed &&
          'Copying is blocked in this window, select the command and copy it by hand'}
      </p>
    </div>
  );
}

export type PackageManagerId = 'npm' | 'pnpm' | 'yarn' | 'bun';

export type InstallCommand = {
  id: PackageManagerId;
  label: string;
  command: string;
};

export const INSTALL_COMMANDS: InstallCommand[] = [
  { id: 'npm', label: 'npm', command: 'npm install @fernpost/sdk' },
  { id: 'pnpm', label: 'pnpm', command: 'pnpm add @fernpost/sdk' },
  { id: 'yarn', label: 'yarn', command: 'yarn add @fernpost/sdk' },
  { id: 'bun', label: 'bun', command: 'bun add @fernpost/sdk' },
];

export const DEFAULT_MANAGER: PackageManagerId = 'npm';

export const CARD = {
  eyebrow: 'Fernpost SDK',
  title: 'Send your first issue from code',
  description:
    'Install the SDK, keep your API key on the server and publish drafts from any script, CMS or scheduled job.',
  links: [
    { label: 'Read the quickstart', href: '#' },
    { label: 'Browse the API reference', href: '#' },
  ],
};
